function parseJsonb(value, fallbackValue) {
  if (value === null || value === undefined) return fallbackValue;
  if (Array.isArray(value)) return value;
  if (typeof value === 'object') return value;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return fallbackValue;
    try {
      return JSON.parse(trimmed);
    } catch (error) {
      return fallbackValue;
    }
  }
  return fallbackValue;
}

function asBoolean(value) {
  if (value === true) return true;
  if (value === false) return false;
  if (typeof value === 'string') return value.toLowerCase() === 'true';
  return false;
}

const row = $input.first().json || {};
const recoveredRunsParsed = parseJsonb(row.recovered_runs, []);
const recoveredRuns = Array.isArray(recoveredRunsParsed) ? recoveredRunsParsed : [];
const lockAcquired = asBoolean(row.lock_acquired);

